<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?= view('partials/breadcrumbs',['title'=>'Audit Logs','subtitle'=>'Security-relevant and operational changes.']) ?><section class="panel"><div class="panel-head"><form class="toolbar" method="get"><input type="search" name="q" value="<?= esc((string)service('request')->getGet('q')) ?>" placeholder="Search actor, action, entity, or message"><button class="btn" type="submit">Search</button><?php if(service('request')->getGet('q')): ?><a class="btn ghost" href="<?= site_url('audit-logs') ?>">Clear</a><?php endif; ?></form></div><p class="result-count"><?= (int)$total ?> audit event(s)</p><div class="table-wrap" role="region" aria-label="Audit log table" tabindex="0"><table><thead><tr><th>Date</th><th>Actor</th><th>Action</th><th>Entity</th><th>Message</th></tr></thead><tbody><?php foreach($logs as $l): ?><tr><td><?= esc(fmt_date($l['created_at'],true)) ?></td><td><?= esc($l['actor_name']??'System') ?></td><td><code><?= esc($l['action']) ?></code></td><td><?= esc($l['entity_type']?:'—') ?><?= $l['entity_id']?' #'.(int)$l['entity_id']:'' ?></td><td><?= esc($l['message']) ?></td></tr><?php endforeach; ?><?php if(empty($logs)): ?><tr><td colspan="5"><div class="empty">No audit activity matches your search.</div></td></tr><?php endif; ?></tbody></table></div><?php if($pagerLinks): ?><div class="pager" aria-label="Audit log pagination"><?= $pagerLinks ?></div><?php endif; ?></section><?= $this->endSection() ?>
